import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"52、【艮】 艮下艮上","description":"周易口訣義 - 52、【艮】 艮下艮上","frontmatter":{"title":"52、【艮】 艮下艮上","description":"周易口訣義 - 52、【艮】 艮下艮上"},"headers":[],"relativePath":"classics/koujueyi/054.md","filePath":"classics/koujueyi/054.md"}'),r={name:"classics/koujueyi/054.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_52、【艮】-艮下艮上" tabindex="-1">52、【艮】 艮下艮上 <a class="header-anchor" href="#_52、【艮】-艮下艮上" aria-label="Permalink to “52、【艮】 艮下艮上”">​</a></h1><p>彖曰：艮，止也。時止則止，時行則行，動靜不失其時，其道光明。「艮其止」，止其所也。上下敵應，不相與也，是以「不獲其身，行其庭，不見其人，無咎」也。</p><p>象曰：兼山，艮，君子以思不出其位。</p><p>初六，艮其趾，無咎，利永貞。</p><p>象曰：「艮其趾」，未失正也。</p><p>六二，艮其腓，不拯其隨，其心不快。</p><p>象曰：「不拯其隨」，未退聽也。</p><p>九三，艮其限，列其夤，厲薰心。</p><p>象曰：「艮其限」，危薰心也。</p><p>六四，艮其身，無咎。</p><p>象曰：「艮其身」，止諸躬也。</p><p>六五，艮其輔，言有序，悔亡。</p><p>象曰：「艮其輔」，以中正也。</p><p>上九，敦艮，吉。</p><p>象曰：「敦艮」之吉，以厚終也。</p><p>解讀</p><p>艮其背，艮者，靜止之義。此卦象山之為體，安然靜止，不動不移，故以為名也。以人事喻之，貪慾之情，傷性壞義，防其動欲，制其未成，故老子云「不見可欲，使心不亂」是也。背者無見之物，今既止在其背，目之不見，即動欲之情不生，故曰</p><p>「艮其背」也。「不獲其身，行其庭，不見其人，無咎」者，夫對面而止，即情有所動，抑傷其情而強使止，患必生焉。今止在其背，故「不獲其身」，雖「行於庭，不見其人」，即「無咎」矣。「象曰兼山，艮」者，孔氏雲：「兩山兼重，謂之兼山也。」直置一山，己能鎮止，兩山重疊，止義彌大，故曰「兼山，艮」也。「君子以思不出其位」者，艮之為義，各止其所，故君子象之，思慮不出己位，不妄動求，不相侵也。</p><p>「初六，艮其趾，無咎，利永貞」者，趾，足也；又處卦之下，即是趾在於足，既止於是，不為躁動而得無咎，故曰「艮其趾，無咎」。靜止之初，心無動欲，其利在於永長貞正，故曰「利永貞」也。</p><p>「六二，艮其腓，不拯其隨，其心不快」者，腓，腨腸也；拯，舉也；隨，謂足也。六二止於腓，腓體動躁，屈伸搖動，皆隨其足。今止在腓腸，足既不舉，腓無由動，故「艮其腓，不拯其隨」也。腓性動躁，而強止之，則傷其本性，情與體乖，故其心不能快樂矣，故曰「其心不快」也。</p><p>「九三，艮其限，裂其夤，厲薰心」者，限是身之中，人繫帶之處，三居兩卦之際，即時止在其限，故曰「艮其限」也。夤，當脊中之肉也；薰，燒灼也。三既處二卦之際，即上下不通，是分裂其夤，身將喪矣。乃憂危之切，故薰灼其心，故曰「厲薰心」也。然君子治國，若治於身，上下不通，君臣不接，故裂夤即身亡，不接則國喪。故王傳雲：「體分兩主，大器喪矣。」大器，謂國之與身也。</p><p>「六四艮其身，無咎」者，已入上體，與九三相得，兩體不分，全乃謂之身。履得其位而全其身，不陷非妄，所以「無咎」也。</p><p>「六五，艮其輔，言有序，悔亡」者，輔，夾車也。六五艮於輔頰之間，即是慎止言語，密於樞機，故曰「口無擇言」，言有倫序，所以「悔亡」，故曰「言有序，悔亡」也。「上九，敦艮，吉」者，敦，厚也；居止之極，敦厚在上，不為妄累所牽，故獲「吉」也。</p>',23)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
